import {installCameraDrag,rotateOrbit,resetOrbit,cameraRelativeIntent} from './animation/camera-controls.mjs';
import {World} from './scene.mjs';
import {createMotion,moveController} from './animation/movement.mjs';
import {installWalkValidation} from './animation/walk-test.mjs';
import {installOfficeTest} from './animation/office-test.mjs';
import {installCandidateTest} from './animation/candidate-test.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let world,state={position:{x:0,z:5.5},office:1,build:null,character:'gaspar'},keys={},joy={x:0,y:0},pointer=null,inspect=false,target=null,playing=true,dismissed=false,last=performance.now(),clock=0,saveAt=0;
const motion=createMotion();let walkValidation=null;const validationMode=new URLSearchParams(location.search).has('walktest')||new URLSearchParams(location.search).has('hotfix3')||new URLSearchParams(location.search).has('officeqa');
try{const p=JSON.parse(localStorage.getItem('drillrun-visual-position'));if(p&&Number.isFinite(p.x)&&Number.isFinite(p.z))state.position=p;}catch{}
function toast(s){$('#toast').textContent=s;$('#toast').classList.remove('hidden');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.add('hidden'),2600);}
function save(){try{localStorage.setItem('drillrun-visual-position',JSON.stringify(state.position));}catch{}}
function resetJoy(){joy={x:0,y:0};pointer=null;$('#joyKnob').style.transform='translate(0,0)';}
function joyMove(e){const r=$('#joystick').getBoundingClientRect(),max=r.width*.3;let x=e.clientX-r.left-r.width/2,y=e.clientY-r.top-r.height/2;const l=Math.hypot(x,y);if(l>max){x*=max/l;y*=max/l;}joy={x:x/max,y:y/max};$('#joyKnob').style.transform=`translate(${x}px,${y}px)`;}
$('#joystick').onpointerdown=e=>{pointer=e.pointerId;e.currentTarget.setPointerCapture(e.pointerId);target=null;joyMove(e);};$('#joystick').onpointermove=e=>{if(e.pointerId===pointer)joyMove(e);};$('#joystick').onpointerup=$('#joystick').onpointercancel=$('#joystick').onlostpointercapture=resetJoy;
function setInspect(v,mode="office"){inspect=v;world.inspect=v;$('#officeValidation')?.classList.toggle('hidden',v);world.inspectMode=mode;world.zoom=1;$('#officePlan').classList.toggle('hidden',!v||mode!=='office'||world.inspectAngle!=='plan');$$('[data-angle=plan]').forEach(b=>b.classList.toggle('hidden',mode==='worker'));target=null;resetJoy();$('#inspection').classList.toggle('hidden',!v);$('#gameUI').classList.toggle('inspecting',v);$('#walkView').classList.toggle('active',!v);$('#officeView').classList.toggle('active',v&&mode==='office');$('#workerView').classList.toggle('active',v&&mode==='worker');$('#objective').classList.toggle('hidden',v);$('#worldLabels').style.display=v?'none':'';if(v){world.grid.visible=false;$('#gridView').classList.remove('active');}}
$('#officeView').onclick=$('#interact').onclick=()=>setInspect(true);$('#workerView').onclick=()=>setInspect(true,'worker');$('#walkView').onclick=$('#backWalk').onclick=()=>setInspect(false);$('#gridView').onclick=()=>{world.grid.visible=!world.grid.visible;$('#gridView').classList.toggle('active',world.grid.visible);if(world.grid.visible)toast('Retícula modular · subdivisiones de ⅓ de módulo.');};$$('[data-angle]').forEach(b=>b.onclick=()=>{world.inspectAngle=b.dataset.angle;$('#officePlan').classList.toggle('hidden',b.dataset.angle!=='plan'||world.inspectMode!=='office');$$('[data-angle]').forEach(x=>x.classList.toggle('selected',x===b));});
$('#officeDoor').onclick=()=>{const d=world.officeDoor();if(d&&!world.toggleOfficeDoor(d.id))toast('Deja libre el recorrido de la puerta para abrir o cerrar.');};
$('#zoomIn').onclick=()=>world.zoom=Math.max(.7,world.zoom-.12);$('#zoomOut').onclick=()=>world.zoom=Math.min(1.4,world.zoom+.12);$('#homeView').onclick=()=>{world.zoom=1;resetOrbit(world.orbit);};
$('#helpButton').onclick=()=>{keys={};target=null;resetJoy();$('#helpPanel').classList.remove('hidden');};$('#closeHelp').onclick=$('#helpStart').onclick=()=>$('#helpPanel').classList.add('hidden');
$('#fullscreenButton').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('La pantalla completa depende del navegador de tu teléfono.');}catch{toast('No se pudo activar pantalla completa.');}};
function rotate(){const portrait=innerHeight>innerWidth&&innerWidth<800;$('#rotateHint').classList.toggle('hidden',!portrait||dismissed);}$('#dismissRotate').onclick=()=>{dismissed=true;rotate();};addEventListener('resize',rotate);
addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys[e.key.toLowerCase()]=true;if(e.key.toLowerCase()==='e'&&!e.repeat)setInspect(!inspect);if(e.key==='Escape'){setInspect(false);$('#helpPanel').classList.add('hidden');}});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);addEventListener('blur',()=>{keys={};resetJoy();save();});addEventListener('pagehide',save);
function move(dt){let sx=joy.x,sy=joy.y;if(keys.w||keys.arrowup)sy--;if(keys.s||keys.arrowdown)sy++;if(keys.a||keys.arrowleft)sx--;if(keys.d||keys.arrowright)sx++;let dx=0,dz=0;const l=Math.hypot(sx,sy);if(l>.025){target=null;sx/=Math.max(1,l);sy/=Math.max(1,l);const relative=cameraRelativeIntent(.8*sx+.6*sy,-.6*sx+.8*sy,world.orbit.yaw);dx=relative.x;dz=relative.z;}else if(target){const x=target.x-state.position.x,z=target.z-state.position.z,len=Math.hypot(x,z);if(len<.09)target=null;else{const intensity=Math.min(1,len/.4);dx=x/len*intensity;dz=z/len*intensity;}}
 const qaIntent=walkValidation?.input(dt);if(qaIntent){dx=qaIntent.x;dz=qaIntent.z;}
 const result=moveController(state.position,motion,{x:dx,z:dz},dt,(x,z)=>world.isBlocked(x,z,.33,state));world.player.rotation.y=result.yaw;if(!result.distance&&target&&Math.hypot(dx,dz)>.1)target=null;return result.speed>.025;}
function frame(now){if(!validationMode)requestAnimationFrame(frame);const dt=Math.min(.08,(now-last)/1000);last=now;clock+=dt;const canMove=(!inspect||walkValidation?.active)&&$('#helpPanel').classList.contains('hidden')&&$('#rotateHint').classList.contains('hidden');if(!canMove){motion.vx=motion.vz=0;motion.speed=0;}const walking=canMove?move(dt):false;world.update(state,dt,clock,walking,false,false);const door=world.officeDoor();$('#officeDoor').classList.toggle('hidden',!door||inspect);if(door)$('#officeDoor').textContent=(world.office.userData.api.opened[door.id]?'Cerrar ':'Abrir ')+door.name;const l=world.labels.find(x=>x.id==='office'),p=world.project(l.point),label=$('#officeLabel');label.style.left=p.x+'px';label.style.top=p.y+'px';label.style.display=!inspect&&p.visible?'':'none';if(now-saveAt>2500){save();saveAt=now;}}
try{world=new World($('#world'));await world.characterReady;world.setCharacter('gaspar');if(world.isBlocked(state.position.x,state.position.z,.33,state))state.position={x:0,z:5.5};world.inspectAngle='three';motion.turnBeforeMove=world.candidateActive;if(new URLSearchParams(location.search).has('officeqa'))walkValidation=installOfficeTest({world,state,motion,setInspect,resetJoy});if(new URLSearchParams(location.search).has('hotfix3'))walkValidation=installCandidateTest({world,state,motion,setInspect,resetJoy});if(new URLSearchParams(location.search).has('walktest'))walkValidation=installWalkValidation({world,state,motion,setInspect,resetJoy});const label=document.createElement('button');label.id='officeLabel';label.className='worldLabel';label.textContent='OFICINA · MÓDULO 01';label.onclick=()=>setInspect(true);$('#worldLabels').append(label);const c=world.renderer.domElement;installCameraDrag(c,{canLook:()=>!inspect&&$('#helpPanel').classList.contains('hidden'),onLook:(dx,dy)=>{target=null;rotateOrbit(world.orbit,dx,dy);},onTap:(x,y)=>{if(inspect)return;const p=world.pick(x,y);if(p&&!world.isBlocked(p.x,p.z,.35,state))target={x:p.x,z:p.z};}});if(world.renderer.isSoftwareRenderer)$('#renderMode').textContent='Vista compatible · iluminación simplificada';rotate();if(validationMode)setInterval(()=>frame(performance.now()),1000/30);else requestAnimationFrame(frame);setTimeout(()=>{$('#loading').classList.add('hidden');$('#gameUI').classList.remove('hidden');},400);}catch(e){console.error(e);$('#loadMessage').textContent='No se pudo iniciar la escena. Recarga en un navegador actualizado.';}
